            .boost-sd__instant-search-placeholder {
              display: inline-block;
              width: 100%;
              max-width: 100%;
              min-width: 224px;
              background-color: #fff;
            }

            .boost-sd__instant-search-placeholder-list {
              padding: 0;
              margin: 10px 10px 0;
              list-style: none;
            }

            .boost-sd__instant-search-placeholder-item {
              position: relative;
              height: 45px;
              margin-bottom: 10px;
            }

            .boost-sd__instant-search-placeholder-item::marker {
              font-size: 0;
            }

            .boost-sd__instant-search-placeholder-item::before {
              content: '';
              position: absolute;
              top: 8px;
              left: 55px;
              display: inline-block;
              width: calc(100% - 55px);
              height: 10px;
              background: -webkit-gradient(linear,
                  left top,
                  right top,
                  color-stop(8%, #eee),
                  color-stop(18%, #e6e6e6),
                  color-stop(33%, #eee));
              background-color: #eee;
              border-radius: 50em;
              animation: place-holder-shimmer 1s linear infinite forwards;
            }

            .boost-sd__instant-search-placeholder-item::after {
              content: '';
              position: absolute;
              top: 28px;
              left: 55px;
              display: inline-block;
              width: 50%;
              height: 10px;
              background: -webkit-gradient(linear,
                  left top,
                  right top,
                  color-stop(8%, #eee),
                  color-stop(18%, #e6e6e6),
                  color-stop(33%, #eee));
              background-color: #eee;
              border-radius: 50em;
