              max-width: 45px;
              background-color: #f5f5f5;
            }

            .boost-sd__instant-search-placeholder-img:empty {
              display: block;
            }

            [dir='rtl'] .boost-sd__instant-search-placeholder-item::before {
              left: auto;
              right: 55px;
            }

            [dir='rtl'] .boost-sd__instant-search-placeholder-item::after {
              left: auto;
              right: 55px;
            }

            /* Suggestion placeholder */
            @keyframes place-holder-shimmer {
              0% {
                background-position: -150px 0;
              }

              100% {
                background-position: 150px 0;
