        {% assign autocompleteClasses1 = autocompleteClasses1 | append: 'boost-sd__instant-search-no-product ' %}
        {% endif %}
        <div class='boost-sd__instant-search-autocomplete {{ autocompleteClasses }} boost-sd__g-flexColumn'>
