                <img class="boost-sd__product-banner-image" src="{{ banner.imgSrc }}" alt="{{ banner.name }}" width="auto" height="auto" />
              </a>
            </div>
          </div>
          {% endif %}
          {% endfor %}
          {% endif %}
          <!-- End logic banner  -->
          <!-- TEMPLATE GRID PRODUCT ITEM -->
          {% if product.original_images != nil %}
          {% assign imageArray = product.original_images %}
          {% else %}
          {% assign imageArray = product.images_info %}
          {% endif %}
          {% assign productId = product.id %}
          {% if product.variant_id %}
          {% assign productId = product.variant_id %}
          {% endif %}
          {% assign filterOptionIdImageBaseOn = 'pf_opt_color' %}
          {% capture filterOptionIdImageBaseOn %}{% endcapture %}
          {% assign optionName = filterOptionIdImageBaseOn | replace: 'pf_opt_', '' %}
          {% assign filterValues = request[filterOptionIdImageBaseOn] %}
          {% assign selectedVariantImageByFilterOption = nil %}
          {% for item in product.variants %}
          {% for filterValue in filterValues %}
          {% assign optionNameValue = optionName | append: ":" | append: filterValue | strip %}
          {% if item.merged_options contains optionNameValue %}
          {% if item.image %}
          {% assign selectedVariantImageByFilterOption = item.image %}
          {% break %}
          {% endif %}
          {% endif %}
          {% endfor %}
          {% if selectedVariantImageByFilterOption != nil %}
          {% break %}
          {% endif %}
          {% endfor %}
          {% capture productVariants %}
          [
          {% for variant in product.variants %}
          {% assign preorder = '{}' %}
          {% if variant.preorder and variant.preorder != nil %}
          {% assign preorder = variant.preorder %}
          {% else %}
          {% assign preorder = '' %}
          {% endif %}
          {
          "title": "{{ variant.title }}",
          "id": "{{ variant.id }}",
          "available": {{ variant.available }},
          "preorder": {{ preorder | json }}
          }{% unless forloop.last %},{% endunless %}
          {% endfor %}
          ]
          {% endcapture %}
          {% capture productData %}
          {
          "handle": "{{ product.handle }}",
          "variantId": "{{ product.variant_id }}",
          "splitProduct": "{{ product.split_product }}",
          "variants": {{ productVariants | json | escape }},
          "priceMin": "{{ product.price_min }}",
          "priceMax": "{{ product.price_max }}",
          "compareAtPriceMin": "{{ product.compare_at_price_min }}",
          "compareAtPriceMax": "{{ product.compare_at_price_max }}",
          "images": {{ imageArray | json | escape }},
          "options_with_values": {{ product.options_with_values | json | escape }},
          "selectedVariantImageByFilterOption": "{{ selectedVariantImageByFilterOption | escape }}",
          "category": "{{ product.product_type | escape }}",
          "tags" : {{ product.tags | json | escape }}
          }
          {% endcapture %}
          {%- capture borderLayoutSetting %}noBorder{% endcapture -%}
          {% if borderLayoutSetting == 'noPadding' %}
          {% assign borderLayoutItem = 'no-padding' %}
          {% elsif borderLayoutSetting == 'hasPadding' %}
          {% assign borderLayoutItem = 'border-has-padding' %}
          {% elsif borderLayoutSetting == 'noPaddingImage' %}
          {% assign borderLayoutItem = 'border-no-padding-image' %}
          {% else %}
          {% assign borderLayoutItem = 'no-border' %}
          {% endif %}
          {% assign productLocale = '' %}
          {% if request.current_locale != "" or request.current_locale != null %}
          {% assign productLocale = request.current_locale %}
          {% endif %}
          <div class='boost-sd__product-item boost-sd__product-item--{{ borderLayoutItem }}  boost-sd__product-item-grid-view-layout' id='{{ product.id }}' data-product-id='{{ productId }}' data-product='{{ productData | json_encode }}'>
            <!-- TEMPLATE GRID PRODUCT ITEM - PRODUCT IMAGE -->
            {%- capture aspectRatioSetting %}square{% endcapture -%}
            {% capture hoverEffect %}reveal-second-image{% endcapture %}
            {% assign productImages = product.images_info %}
            {% if product.split_product %}
            {% assign productImages = product.original_images %}
            {% endif %}
            <div class="boost-sd__product-item-grid-view-layout-image">
              <div class="boost-sd__product-link-image">
                <div style="position: relative">
                  {% assign effectClasses = '' %}
                  {% if hoverEffect == 'reveal-second-image-and-zoom-in' %}
                  {% assign effectClasses = effectClasses | append: 'boost-sd__product-image-wrapper--zoom-in' %}
                  {% if productImages.size > 1 %}
                  {% assign effectClasses = effectClasses | append: ' boost-sd__product-image-wrapper--has-second-image' %}
                  {% endif %}
                  {% endif %}
                  {% if hoverEffect == 'reveal-second-image' and productImages.size > 1 %}
                  {% assign effectClasses = effectClasses | append: 'boost-sd__product-image-wrapper--has-second-image' %}
                  {% endif %}
                  {% if hoverEffect == 'zoom-in' %}
                  {% assign effectClasses = effectClasses | append: 'boost-sd__product-image-wrapper--zoom-in' %}
                  {% endif %}
                  {% assign aspectRatio = '' -%}
                  {% if aspectRatioSetting == 'natural' -%}
                  {% assign imageWidth = product.images_info[0].width -%}
                  {% assign imageHeight = product.images_info[0].height -%}
                  {% assign aspectRatio = aspectRatio | append: 'aspect-ratio: ' | append: imageWidth | append: '/' | append: imageHeight -%}
                  {% endif -%}
                  <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--crop-center {{ effectClasses }} boost-sd__product-image-wrapper--square" style="{{ aspectRatio }}">
                    <a aria-label="{{ product.title | escape }}" class="boost-sd__product-link boost-sd__product-image" {%- if request.previewMode != true %} href="/products/{{ product.handle }}" {% endif -%}>
                      {% assign firstImageSrc = '' -%}
                      {% if selectedVariantImageByFilterOption != nil -%}
                      {% assign firstImageSrc = selectedVariantImageByFilterOption -%}
                      {% else -%}
                      {% assign firstImageSrc = product.images_info[0].src -%}
                      {% endif -%}
                      {% assign widthParam = "&width=" -%}
                      {% assign widths = "200,300,400,500,700,800" | split: "," -%}
                      {% if request.device contains 'mobile' -%}
                      {% assign maxWidth = 400 -%}
                      {% else -%}
                      {% assign maxWidth = 700 -%}
                      {% endif -%}
                      {% if request.productImageWidth != blank -%}
                      {% assign imageWidth = request.productImageWidth | plus: 0 -%}
                      {% if imageWidth > maxWidth -%}
                      {% assign maxWidth = imageWidth -%}
                      {% endif -%}
                      {% endif -%}
                      {% if product.images_info[0] -%}
                      {% capture srcset -%}
                      {% for width in widths -%}
                      {% assign widthNo = width | plus: 0 %}
                      {% if widthNo < maxWidth -%}
                      {{ firstImageSrc }}{{ widthParam }}{{ width }} {{ width }}w,
                      {% else -%}
                      {{ firstImageSrc }}{{ widthParam }}{{ maxWidth }} {{ maxWidth }}w
                      {% break -%}
                      {% endif -%}
                      {% endfor -%}
                      {% endcapture -%}
                      {% assign productPerRow = 4 -%}
                      {% if request.productPerRow != blank -%}
                      {% assign productPerRow = request.productPerRow | plus: 0 -%}
                      {% endif -%}
                      <img id="product-image-{{ product.id }}" class="boost-sd__product-image-img boost-sd__product-image-img--main" {% if index and index < productPerRow -%} loading="eager" {% else -%} loading="lazy" {% endif -%} decoding="async" alt="{{ product.title | escape }}" src="{{ firstImageSrc }}&amp;width=200" srcset="{{ srcset }}" width="auto" height="auto" />
                      {% if productImages.size > 1 and hoverEffect == 'reveal-second-image-and-zoom-in' or hoverEffect == 'reveal-second-image' %}
                      {% for image in productImages %}
                      {% if image.src contains product.images_info[0].src %}
                      {% assign secondImage = productImages[image.position] %}
                      {% endif %}
                      {% endfor %}
                      {% if secondImage -%}
                      {% assign secondImageSrc = secondImage.src -%}
                      {% capture secondImageSrcset -%}
                      {% for width in widths -%}
                      {% assign widthNo = width | plus: 0 -%}
                      {% if widthNo < maxWidth -%}
                      {{ secondImageSrc }}{{ widthParam }}{{ width }} {{ width }}w,
                      {% else -%}
                      {{ secondImageSrc }}{{ widthParam }}{{ maxWidth }} {{ maxWidth }}w
                      {% break -%}
                      {% endif -%}
                      {% endfor -%}
                      {% endcapture -%}
                      <img width="auto" height="auto" {% if index and index < productPerRow -%} loading="eager" {% else -%} loading="lazy" {% endif -%} class="boost-sd__product-image-img boost-sd__product-image-img--second" alt="{{ product.title | escape }}" src="{{ secondImage.src }}&amp;width=200" srcset="{{ secondImageSrcset }}">
                      {% endif -%}
                      {% endif %}
                      {% else -%}
                      <img id="product-image-{{ product.id }}" class="boost-sd__product-image-img boost-sd__product-image-img--main" alt="{{ product.title | escape }}" src="https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268" width="auto" height="auto" />
                      {% endif -%}
                    </a>
                    <div class="boost-sd__product-image-row boost-sd__product-image-row--top ">
                      <div class="boost-sd__product-image-column boost-sd__product-image-column--in-top boost-sd__product-image-column--left">
                        {% assign hideOtherLabelsWhenSoldOut = true -%}
