                        <button aria-label='{{ selectOptionBtnLabel }}' class='boost-sd__button boost-sd__button--select-option boost-sd__button--border boost-sd__button--show-on-hover boost-sd__button--hide-on-mobile boost-sd__button--rectangle{{ buttonPreorder }}' type='button' {% if product.available == false %} disabled {% endif %} data-metadata='{{ metaData | json_encode }}'>
                          <span class='boost-sd__icon boost-sd__icon--is-image boost-sd__icon--fill-current-color'></span>
