                                </label>
                                {% else -%}
                                <label role="radio" tabindex="0" aria-label="{{ swatch.original_name }}:{{ value.title }}" for="product-swatch-qv-{{ product.id }}-{{ value.title | strip_html | escape }}" class="boost-sd__radio-label boost-sd__radio-label--in-quick-view">
                                  {{ value.title | strip_html | escape }}
                                </label>
                                {% endif -%}
                              </div>
                            </div>
                          </div>
                          {% endfor -%}
                        </div>
                      </div>
                      {% endfor -%}
                    </div>
                    <button type="button" class="boost-sd__button boost-sd__button--primary boost-sd__button--add-to-cart boost-sd__button--full-width boost-sd__button--large boost-sd__btn-add-to-cart">
                      <span class="boost-sd__button-text boost-sd__cta-button-text">{{ "productItem.atcAvailableLabel" | translate: translations, 'Add to cart' }}</span>
                    </button>
                    <button type="button" aria-label='{{ "close" | translate: translations, "Close" }}' class="boost-sd__button boost-sd__button--transparent boost-sd__button--float boost-sd__popup-select-option-close-btn">
                      <svg width="17" height="17" viewBox="0 0 17 17" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path fill-rule="evenodd" clip-rule="evenodd" d="M12.9024 3.56904C13.0325 3.43886 13.0325 3.22781 12.9024 3.09763C12.7722 2.96746 12.5611 2.96746 12.431 3.09763L8 7.5286L3.56904 3.09763C3.43886 2.96746 3.22781 2.96746 3.09763 3.09763C2.96746 3.22781 2.96746 3.43886 3.09763 3.56904L7.5286 8L3.09763 12.431C2.96746 12.5611 2.96746 12.7722 3.09763 12.9024C3.22781 13.0325 3.43886 13.0325 3.56904 12.9024L8 8.47141L12.431 12.9024C12.5611 13.0325 12.7722 13.0325 12.9024 12.9024C13.0325 12.7722 13.0325 12.5611 12.9024 12.431L8.47141 8L12.9024 3.56904Z" fill="#222222"></path>
                      </svg>
                    </button>
                  </div>
                  <!-- POPUP -->
                </div>
              </div>
            </div>
            <!-- TEMPLATE GRID PRODUCT ITEM - PRODUCT INFO -->
            <div class="boost-sd__product-info-wrapper">
              <div class="boost-sd__product-info boost-sd__product-info--center">
                <a aria-label="{{ product.title | escape }}" class="boost-sd__product-link" {% if request.previewMode != true %} href="{{ productLocale }}/products/{{ product.handle }}" {% endif %}>
                  <div class="boost-sd__product-title" id="product-title-{{ product.id }}">
                    {{ product.title | escape }}
                  </div>
                </a>
                <div class="boost-sd__product-price" id="product-price-{{ product.id }}">
                  <!-- This Template contains a few variables built from the client js side -->
                  {% assign removePriceDecimal = false -%}
                  {% assign decimalDelimiter = '' -%}
                  {% assign withoutTrailingZeros = true -%}
                  {% assign showCentAsSuperscript = false -%}
                  {% assign moneyFormat = request.money_format | strip_html -%}
                  {% assign showSavingDisplay = false -%}
                  {% assign minPrice = product.price_min | times: 1.0 -%}
                  {% assign maxPrice = 0 -%}
                  {% if product.price_max -%}
                  {% assign maxPrice = product.price_max | times: 1.0 -%}
                  {% endif -%}
                  <!-- convert variable compareAtPriceMin to number -->
                  {% assign compareAtPriceMin = 0 -%}
                  {% if product.compare_at_price_min -%}
                  {% assign compareAtPriceMin = product.compare_at_price_min | times: 1.0 -%}
                  {% endif -%}
                  {% assign isSale = false -%}
                  {% assign salePercent = 0 -%}
                  {% assign saleAmount = 0 -%}
                  {% if compareAtPriceMin > minPrice -%}
                  {% assign isSale = true -%}
                  {% endif -%}
                  {% assign compareAtPriceWithFormat = '' -%}
                  {% unless compareAtPriceMin == null or compareAtPriceMin == 0 or isSale == false -%}
                  <!-- calculate salePercent base on compareAtPriceMin and minPrice -->
                  {% assign compare = compareAtPriceMin | minus: minPrice | times: 100 -%}
                  {% assign salePercent = compare | divided_by: compareAtPriceMin | ceil | append: '%' -%}
                  <!-- compareAtPriceWithFormat is compare price with PriceMin and format currency -->
                  {% assign compareAtPriceWithFormat = compareAtPriceMin | format_currency: moneyFormat, showCentAsSuperscript, removePriceDecimal, decimalDelimiter, withoutTrailingZeros -%}
                  {% assign saleAmount = compareAtPriceMin | minus: minPrice -%}
                  {% endunless -%}
                  <!-- Format price min -->
                  {% assign priceMinWithFormat = minPrice | format_currency: moneyFormat, showCentAsSuperscript, removePriceDecimal , decimalDelimiter, withoutTrailingZeros -%}
                  <!-- Format price max -->
                  {% assign priceMaxWithFormat = '' -%}
                  {% if product.price_max and maxPrice > minPrice -%}
                  {% assign priceMaxWithFormat = maxPrice | format_currency: moneyFormat, showCentAsSuperscript, removePriceDecimal , decimalDelimiter, withoutTrailingZeros -%}
                  {% endif -%}
                  <!-- priceMax used for multi variant price display where it can have min-max price with format and translation -->
                  {% assign hasMultiVariantPrice = false -%}
                  {% if translations.productItem.amount contains "minPrice" -%}
                  {% assign hasMultiVariantPrice = true -%}
                  {% endif -%}
                  {% assign isSamePrice = true -%}
                  {% if minPrice != maxPrice or product.compare_at_price_min != product.compare_at_price_max -%}
                  {% assign isSamePrice = false -%}
                  {% endif -%}
                  {% assign priceValueWithFormat = priceMinWithFormat -%}
                  {% if isSamePrice == false and maxPrice > minPrice and hasMultiVariantPrice -%}
                  {% assign priceValueWithFormat = "productItem.amount" | translate: translations, "" | replace: '{{minPrice}}', priceMinWithFormat | replace: '{{maxPrice}}', priceMaxWithFormat -%}
                  {% endif -%}
                  {% assign savingPriceWithFormat = '' -%}
                  {% unless showSavingDisplay == false or saleAmount == 0 -%}
                  {% assign saleAmountWithFormat = saleAmount | format_currency: moneyFormat, showCentAsSuperscript, removePriceDecimal, decimalDelimiter, withoutTrailingZeros -%}
                  {% assign savingPriceWithFormat = "productItem.savingAmount" | translate: translations, "Save {{saleAmount}}" | replace: '{{saleAmount}}', saleAmountWithFormat | replace: '{{salePercent}}', salePercent -%}
                  {% endunless -%}
                  <!-- Price compare display top or bottom -->
                  <!-- Price compare display left or right -->
                  <div aria-label="Sale price {{ priceValueWithFormat }}{% if compareAtPriceWithFormat != '' -%}, Regular price {{ compareAtPriceWithFormat }}{% endif -%}{% if savingPriceWithFormat != '' -%}, Saving {{ savingPriceWithFormat }}{% endif -%}" tabindex="0" class="boost-sd__product-price-wrapper">
                    <span aria-hidden="true" class="boost-sd__product-price-content   boost-sd__product-price-content--text-align-center">
                      <span class="{% if isSale == true %}boost-sd__product-price--sale{% else %}boost-sd__product-price--default{% endif %}">
                        <span class="boost-sd__format-currency">{{ priceValueWithFormat }}</span>
                      </span>
                      {% if compareAtPriceWithFormat != '' -%}
                      <span class="boost-sd__format-currency boost-sd__format-currency--price-compare boost-sd__product-price--compare">
                        <span class="boost-sd__format-currency">{{ compareAtPriceWithFormat }}</span>
                      </span>
                      {% endif -%}
                    </span>
                    {% if savingPriceWithFormat != '' -%}
                    <span aria-hidden="true" class="boost-sd__product-price--saving">
                      <span class="boost-sd__format-currency">{{ savingPriceWithFormat }}</span>
                    </span>
                    {% endif -%}
                  </div>
                </div>
                <!--  PRODUCT INVENTORY -->
                <!-- TEMPLATE PRODUCT SWATCH -->
                {% assign swatches = '' %}
              </div>
            </div>
          </div>
          {% endif %}
          {% endfor %}
          <!-- show banners if  position > productSize -->
          {% if banners.size > 0 and productSize > 0 and request.viewAs != 'list' %}
          {% for banner in banners %}
          {% if banner.position >= productSize %}
          <div class='boost-sd__product-item boost-sd__product-item--{{ borderLayoutItem }} boost-sd__product-item-grid-view-layout boost-sd__product-item--last'>
            {%- capture aspectRatioSetting %}square{% endcapture -%}
            {% assign aspectRatio = '' -%}
            {% if aspectRatioSetting == 'natural' -%}
            {% for product in products %}
            {% assign imageWidth = product.images_info[0].width -%}
            {% assign imageHeight = product.images_info[0].height -%}
            {% endfor %}
            {% assign aspectRatio = aspectRatio | append: 'aspect-ratio: ' | append: imageWidth | append: '/' | append: imageHeight -%}
            {% endif -%}
            <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--square" style="{{ aspectRatio }}">
              <div class="boost-sd__product-banner boost-sd__product-banner--center">
                <a class="boost-sd__product-banner-link" href="{{ banner.link }}" target="{% if banner.openInNewTab == true %}_blank{% else %}_self{% endif %}" alt="{{ banner.name }}">
                  <img class="boost-sd__product-banner-image" src="{{ banner.imgSrc }}" alt="{{ banner.name }}" width="auto" height="auto" />
                </a>
              </div>
            </div>
          </div>
          {% endif %}
          {% endfor %}
          {% endif %}
          <!-- End show banners if  position > productSize -->
        </div>
        {% assign position = 'bottom' %}
        <!-- TEMPLATE PAGINATION -->
        {% assign requestLimit = request.limit | times: 1.0 -%}
        {% assign totalPage = total_product | times: 1 | divided_by: requestLimit | ceil -%}
        {% assign showLoadPrev = false %}
        {% if request.page != 1 and position == 'top' %}
        {% assign showLoadPrev = true %}
        {% endif %}
        {% assign showLoadMore = false %}
        {% if request.page != totalPage and position == 'bottom' %}
        {% assign showLoadMore = true %}
        {% endif %}
        {% if showLoadPrev %}
        {% endif %}
        {% if showLoadMore %}
        {% endif %}
        <!-- TEMPLATE PAGINATION PAGE LINK -->
        {% assign requestLimit = request.limit | times: 1.0 -%}
        {% assign totalPage = total_product | times: 1 | divided_by: requestLimit | ceil -%}
        {% if totalPage > 1 %}
        {% assign pagination = request.page | pagination_list: totalPage | split: "," %}
        <div class="boost-sd__pagination boost-sd__pagination--center">
          {% if request.page != 1 %}
          <button type="button" aria-label="previous page" class="boost-sd__pagination-button boost-sd__pagination-button--circle boost-sd__pagination-button--prev">
            <span class="boost-sd__pagination-button-icon boost-sd__pagination-button-icon--left">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 7 12" height="12" width="7">
                <path d="M6.80474 0.528514C6.54439 0.268165 6.12228 0.268165 5.86193 0.528514L0.861929 5.52851C0.601579 5.78886 0.601579 6.21097 0.861929 6.47132L5.86193 11.4713C6.12228 11.7317 6.54439 11.7317 6.80474 11.4713C7.06509 11.211 7.06509 10.7889 6.80474 10.5285L2.27614 5.99992L6.80474 1.47132C7.06509 1.21097 7.06509 0.788864 6.80474 0.528514Z" clip-rule="evenodd" fill-rule="evenodd"></path>
              </svg>
            </span>
          </button>
          {% endif %}
          {% for page_string in pagination %}
          {% assign page = page_string | plus: 0 %}
          {% if page == 0 %}
          <button aria-hidden="true" class="boost-sd__pagination-number boost-sd__pagination-number--disabled boost-sd__pagination-number--circle">...</button>
          {% elsif page == request.page %}
          <button aria-label="Current Page {{ page }}" class="boost-sd__pagination-number boost-sd__pagination-number--circle boost-sd__pagination-number--active">{{ page | escape }}</button>
          {% else %}
          <button aria-label="Go to Page {{ page }}" class="boost-sd__pagination-number boost-sd__pagination-number--circle">{{ page | escape }}</button>
          {% endif %}
          {% endfor %}
          {% if request.page != totalPage and totalPage != 0 %}
          <button type="button" aria-label="next page" class="boost-sd__pagination-button boost-sd__pagination-button--circle boost-sd__pagination-button--next">
            <span class="boost-sd__pagination-button-icon boost-sd__pagination-button-icon--right">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 7 12" height="12" width="7">
                <path d="M0.195262 0.528514C0.455612 0.268165 0.877722 0.268165 1.13807 0.528514L6.13807 5.52851C6.39842 5.78886 6.39842 6.21097 6.13807 6.47132L1.13807 11.4713C0.877722 11.7317 0.455612 11.7317 0.195262 11.4713C-0.0650874 11.211 -0.0650874 10.7889 0.195262 10.5285L4.72386 5.99992L0.195262 1.47132C-0.0650874 1.21097 -0.0650874 0.788864 0.195262 0.528514Z" clip-rule="evenodd" fill-rule="evenodd"></path>
              </svg>
            </span>
          </button>
          {% endif %}
        </div>
        {% endif %}
        {% if showLoadPrev %}
        {% endif %}
        {% if showLoadMore %}
        {% endif %}
        {% endif %}
      </div>
    </div>
  </div>
  {% if statusNewSI == 'true'%}
</div>
{% endif %}"}
